    consent: NotRequired[ConnectionConsentSettings]

    content: NotRequired[ConnectionContentSettings]

    crawl: NotRequired[ConnectionCrawlSettings]

    dataset: NotRequired[ConnectionDatasetSettings]

    effect: NotRequired[ConnectionEffectSettings]

    egress: NotRequired[ConnectionEgressSettings]

    export: NotRequired[ConnectionExportSettings]

    extraction: NotRequired[ConnectionExtractionSettings]

    fetch: NotRequired[ConnectionFetchSettings]

    filter_lists: NotRequired[ConnectionFilterListsSettings]

    frontier: NotRequired[ConnectionFrontierSettings]

    governor: NotRequired[ConnectionGovernorSettings]

    identified: NotRequired[ConnectionIdentifiedSettings]

    live_view: NotRequired[ConnectionLiveViewSettings]

    network: NotRequired[ConnectionNetworkSettings]

    paid_fetch: NotRequired[ConnectionPaidFetchSettings]

    politeness: NotRequired[ConnectionPolitenessSettings]

    provenance: NotRequired[ConnectionProvenanceSettings]

