class RunFetchRedirectSettings(TypedDict):
    """The `fetch.redirect` settings of `CrawlSettings`."""

    max: NotRequired[int]
    """How many redirects a crawl request's fetch follows, a refresh stub's hop counted as one: 19 by default, as many as the browser follows in a navigation, from 1 to 19; any other value is refused with `setting_invalid` when the crawl starts. One more fails the request with `too_many_redirects`, so a redirect loop costs a site this many requests and one more. To hand a redirect to the handler unfollowed, list its status in `crawl.handle_statuses`.

    `fetch.redirect.max`.
    """


class RunFetchRefreshSettings(TypedDict):
    """The `fetch.refresh` settings of `CrawlSettings`."""

    max_delay: NotRequired[timedelta | None]
    """The longest delay of a refresh stub a crawl request's fetch follows: a `Refresh` header, or a `<meta http-equiv="refresh">` outside `<noscript>`, to another URL with a delay up to this is followed at once as one more hop, counted in `fetch.redirect.max`. 100 s by default; `0` follows instant refreshes only, and `null` any delay. A refresh with no URL or to the document's own is never followed.

    `fetch.refresh.max_delay`.
    """


class RunFetchSampleSettings(TypedDict):
    """The `fetch.sample` settings of `CrawlSettings`."""

    count: NotRequired[int]
    """How many of a Label's first requests on a domain are samples under `fetch.tier: auto`, each fetched on `http` and then on `browser`, whose run commits, from two Sessions that share nothing where `fetch.http_from` sends the Label's HTTP from the transport, and under `fetch.http_from: learned`, where its `http` run differed, once more on `browser_fetch` from the hop page of the browser run's Session: the Label moves to `http` once all of them gave the same Records and enqueues, and to `browser_fetch` under `learned` once every sample matched there or over `http`. 3 by default; set for the Run only. Fewer than 3 is a weakened control, named in the Run report's `weakened`.

    `fetch.sample.count`.
    """

    refresh_after: NotRequired[FetchSampleRefreshAfter]
    """When a Label's tier choice on a domain under `fetch.tier: auto` is sampled again: after it served `requests` crawl requests, or `after` milliseconds after it was made, whichever comes first; 500 requests or 24 hours (86,400,000 ms) by default. Set for the Run only. A Label whose browser sample showed a consent wall stays on `browser` and is not sampled again.

    `fetch.sample.refresh_after`.
    """


class RunFetchSettings(TypedDict):
    """The `fetch` settings of `CrawlSettings`."""

    block_classification: NotRequired[bool]
    """Whether each document a tier short of the browser serves, its request's own or one a handler's navigation reaches, is read by the Block classification rules (ADR 0035) for a Challenge or a captcha, which moves its request to the browser under `fetch.tier: auto` and ends it `blocked` under a forced tier. On by default. Off, no document is read by them, so nothing a page holds moves its request or ends it `blocked`, and a Challenge page is handled as the page it is; a status the Politeness rule reads, such as 429, still backs its domain off. It is recorded in the Audit log, listed in the run's result, and the Run report's warning `block_classification_off` says so; the Run's Verdict is then `needs_review`, with a reason naming this key (ADR 0029).

    `fetch.block_classification`.
    """

    coalesce: NotRequired[bool]
    """Whether identical GET or HEAD crawl requests in flight at once from one Session, from work items that declare no Effect, wait for one response: the same method, URL, headers and body. Never across Sessions or runs, never for a Paid fetch; Provenance records each response shared. On by default.

    `fetch.coalesce`.
    """

    encoding: NotRequired[str | None]
    """The encoding forced on each crawl request's own document after its BOM, a WHATWG Encoding label such as `shift_jis`, set for the Run or for one of its Labels; none by default. It stands where ADR 0119's order puts it: after the BOM, before the `Content-Type` charset, the `<meta>` prescan and UTF-8. It applies to the request's own document on every attempt, not to a handler's own navigations. A value that is no Encoding label is refused with `setting_invalid` when the crawl starts.

    `fetch.encoding`.
    """

    hedge: NotRequired[RunFetchHedgeSettings]

    http_from: NotRequired[Literal["browser", "learned", "transport"]]
    """Where a Label's HTTP leaves from where the engine chooses its tier, under `fetch.tier: auto`, set for the Run or for one of its Labels; a forced `fetch.tier` ignores it. `browser` sends a sample's `http` run and a Label learned onto `http` from inside the Session's browser, recorded as `browser_fetch`, so the site meets one TLS fingerprint and one cookie jar. `transport` sends them from a Session's own HTTP transport, over its own TLS fingerprint and headers, recorded as `http`: a sample's `http` run and its `browser` run are drawn from two Sessions, one of each client, which share no cookie, storage or local address, and a Label learned onto `http` sends its documents, their redirect hops and its served pages' requests from a Session's own transport. `learned` (the default) behaves as `transport` until the engine learns per Label which client a site accepts: a sample whose `http` run differed runs once more from inside the browser, as does its replay of its browser's calls on `discovered_api`, and its Label keeps the cheapest client that matched every sample. Under either, a request a Session's own transport sent on the tier its Label's comparison chose, which the site refuses as `ip_block` (a 403 whose page says the visitor is blocked; a bare 401 or 403 is no block), retires that Session and drops the Label's choice on the domain: the request runs again as a sample, retried under the Run's retry policy, whose comparison may move the Label to `browser_fetch` or `browser`, and the domain's proxy tier moves up only where the browser's run is refused too. A choice learned under one value is sampled again under another that no longer allows its sender. A pool whose Sessions hold a login, set by a `session.source` or, for a Label's own pool, by its `login`, sends from the browser whatever this says, so the login is never shown under a second client: `config explain` names the Run's `session.source` in this key's `yields_to`, and a `transport` set where such a pool's Sessions open, by the Run on its own pool or by a Label on its pool, fails the crawl's start with `setting_locked`; HTTP credentials and secrets alone hold no login. `transport` is a weakened control, named in the Run report's `weakened` and recorded in the Audit log as `feature_switched_off`; `learned`, the default, and `browser` are not reported weakened.

    `fetch.http_from`.
    """

    kept_responses: NotRequired[RunFetchKeptResponsesSettings]

    light_browser: NotRequired[bool]
    """Whether a crawl may fetch on the `light_browser` tier: Lightpanda, run out of process, its build downloaded on first use into the Browser cache with its pinned digest and never bundled, so its AGPL licence stays outside the distribution. It runs the page's scripts without layout, and its page is the document they leave, so a wait for scripted content is served from it while a call that needs layout, pixels, a script of the handler's or a navigation escalates under `auto` and fails with `browser_required` under a forced tier. Set for the Run only. Off by default: `fetch.tier: light_browser` then fails the crawl's start with `capability_unavailable` naming this key, as it does on a platform Lightpanda builds nothing for.

    `fetch.light_browser`.
    """

    redirect: NotRequired[RunFetchRedirectSettings]

    refresh: NotRequired[RunFetchRefreshSettings]

    sample: NotRequired[RunFetchSampleSettings]

    tier: NotRequired[Literal["auto", "http", "discovered_api", "browser_fetch", "light_browser", "browser"]]
    """The tier that fetches each crawl request's document, set for the Run or for one of its Labels: `auto` (the default) lets the engine choose, whether set or left at the built-in default: it learns the tier per Label on each domain by sample comparison, the first `fetch.sample.count` requests (3) of a Label on a domain each run on `http` and then on `browser`, whose run commits (sent from one Session, or from two that share nothing where `fetch.http_from` sends the Label's HTTP from the transport), and, under `fetch.http_from: learned`, where its `http` run differed, once more on `browser_fetch` from the hop page of the browser run's Session, its run discarded, the Label moving to `http` once all of them staged the same Records (compared after Unicode NFC and whitespace normalization of their strings, in any order) and the same enqueues, the browser's run never matching where it ended on another URL or read its document in another `document.characterSet`, and staying on `browser` for the Run where its browser sample met a consent wall; split by the first segment of its URL paths when its samples disagree by segment (a segment whose own samples disagree stays on `browser`; at most 16 segments per Label and domain, the rest on `browser`), to `browser_fetch` under `learned` once every sample matched there or over `http`, and on `browser` otherwise; a choice is sampled again as `fetch.sample.refresh_after` says; the choice is kept in the run file, so a resumed crawl takes it again, and Provenance records the tier that sent each attempt's document, `browser_fetch` where a document tier's request left from inside the Session's browser, as it does under `auto` unless `fetch.http_from` sends it from the Session's own transport, and whether it was forced; a request on `http` escalates to the browser at the first call that tier cannot serve exactly, in a Session of its own whose client is its browser where the request was sent from a Session's own transport; `http` and `browser` force those tiers, nothing escalating, and a call the forced tier cannot serve fails with `browser_required`; a `standard` Session forced onto `http` sends from its own transport, which presents its browser's `User-Agent` and document request headers (where the browser is an installed one, such as the distribution's Chromium on Linux arm64 and musl, those of the version its executable prints for `--version`, read once per Run without starting a browser; none, with the Run warned `browser_version_unread`, where no browser is installed or it does not print a version and exit within 10 seconds), as do the reads of robots.txt, sitemaps and AI-use signal files that transport sends under every tier, and keeps the Session's cookies in a jar of its own, over reqwest's TLS fingerprint, not the browser's; `light_browser` forces the Lightpanda tier where `fetch.light_browser` allows it, and under `auto` a Run that allows it also runs a sample on `light_browser` where its `http` run differed, the Label moving to `light_browser` once every sample matched there or over `http`; under `auto`, a sample whose `http` run escalated at a network wait also runs on `discovered_api` once its browser run answered: the JSON calls the browser's page made, read as a page-number or cursor plan, are replayed over HTTP for the same request, from the client its `http` run was sent from, and under `fetch.http_from: learned` once more from inside the Session's browser where that replay differed, each replayed call passing the navigation gate, a `page.wait_for_response` armed before a navigation of its page answered from the calls that navigation replays and any other escalating, and a Label whose samples all matched there, or over `http`, moves to `discovered_api`, its later requests replaying the plan for their own pages from the client every sample's replay matched from, its own transport where each matched there and the browser otherwise, which Provenance names in `calls_sent_on`; `browser_fetch` forces the HTTP tier sent from inside the Session's browser context, the one tier that sends HTTP with the browser's own TLS fingerprint, its cookies the Session's, nothing escalating; forcing `discovered_api` is refused with `capability_unavailable` at the crawl's start until a forced tier takes its browser sample.

    `fetch.tier`.
    """

    tier_race: NotRequired[bool]
    """Whether a crawl request races its tiers: the document tier first, sent from where its Label learned to send its HTTP from where `fetch.http_from` is `learned` or `transport` and through browser-fetch otherwise, then the navigation after the Label-on-domain's median latency of that first request, the first result that passes the Page check and the Label's comparison winning, both counting in Politeness and Usage. The loser is cancelled, and Provenance records the race. A race does not feed the sample comparison, so a request whose Label on its domain is due a sample takes the sample instead, and a request a hidden link reached races with no navigation. Set for the Run only: a Label setting it is refused with `setting_not_applicable`, as is a Run switching it on while `politeness.domain.concurrency` is 1, where the navigation could never start. Off by default.

    `fetch.tier_race`.
    """


class RunFilterListsSettings(TypedDict):
    """The `filter_lists` settings of `CrawlSettings`."""

    ads: NotRequired[bool]
    """Whether a browser Session blocks ads by EasyList, as a blocker does: on by default in every Access mode. A blocked request fails as `BlockedByClient`; the never-block list keeps challenge, anti-bot, anti-fraud and payment scripts loading.

    `filter_lists.ads`.
    """

    annoyances: NotRequired[bool]
    """Whether a browser Session blocks page annoyances (social widgets, newsletter and notification prompts) by Fanboy Annoyance, its cookie sections left to the Consent prompt runner: on by default in every Access mode.

    `filter_lists.annoyances`.
    """

    extra: NotRequired[list[str]]
    """Extra Filter lists, by URL or path. Their scriptlets run only when the value comes from an Operator policy or user or project configuration; from a Recipe or a run, only their blocking rules apply.

    `filter_lists.extra`.
    """

    first_party_scripts: NotRequired[bool]
    """Whether a site's own scripts load whatever the Filter lists say: off by default.

    `filter_lists.first_party_scripts`.
    """

    host_cache: NotRequired[int]
    """How many hosts' Clean-up rules this Run keeps built: 1,024, the least used dropped first, and none once the Resource governor finds memory critical. A page on a host it keeps builds no rule list. 0 builds each page's rule list, as before.

    `filter_lists.host_cache`.
    """

    page_scriptlets: NotRequired[bool]
    """Whether the Filter lists' scriptlets that patch a page's JavaScript run, from uBlock Origin's resources downloaded with the lists that name them: off by default, since a site can see them.

    `filter_lists.page_scriptlets`.
    """

    trackers: NotRequired[bool]
    """Whether a browser Session blocks trackers by EasyPrivacy: on by default in every Access mode. A blocked request fails as `BlockedByClient`; the never-block list keeps challenge, anti-bot, anti-fraud and payment scripts loading.

    `filter_lists.trackers`.
    """


class RunFrontierSettings(TypedDict):
    """The `frontier` settings of `CrawlSettings`."""

    learning: NotRequired[bool]
    """Whether the Frontier learns URL rules from the crawl's pages (ADR 0005): each fetched page's Page signature and `rel=canonical`, read with one run of the main-content step, teach it the query parameters with no effect, the equivalent forms, the traps and the pagination that merge or refuse the URLs they show to be one page. On by default. Off, no page is signed and no rule is learned, so the Run report's `learned_rules` is empty and its warning `learning_off` says why, while the fixed URL rules and the check for an exact duplicate stay; it is recorded in the Audit log and listed in the run's result.

    `frontier.learning`.
    """


class RunGovernorBrowserSettings(TypedDict):
    """The `governor.browser` settings of `CrawlSettings`."""

    contexts_per_process: NotRequired[int]
    """How many of a Run's Sessions share one browser process, each in a browser context of its own: 8. The Run's next Session past it gets a process of its own; Sessions of different Runs never share one.

    `governor.browser.contexts_per_process`.
    """

    memory_cap: NotRequired[int | None]
    """The memory, in bytes, of a browser and its processes past which it is recycled; unset by default, when the cap is twice what the browser used once it had opened its first page.

    `governor.browser.memory_cap`.
    """

    page_memory_cap: NotRequired[int]
    """The memory, in bytes, of one page's JavaScript heap and the buffers it holds, past which the Resource governor ends the page while memory is critical: 1 GiB. The page ends at its safe point, once no call on it is in flight, and its calls raise `page_memory_exceeded`, which is retryable.

    `governor.browser.page_memory_cap`.
    """

    recycle_idle: NotRequired[timedelta]
    """How long a browser may hold no open page before it closes, each of its Sessions keeping its cookies and storage for the browser that replaces it: 5 minutes.

    `governor.browser.recycle_idle`.
    """

    recycle_pages: NotRequired[int]
    """How many pages a browser opens before it is recycled: 100. Recycled, it opens no new page, closes once its pages are done and is replaced, each of its Sessions keeping its cookies and storage.

    `governor.browser.recycle_pages`.
    """


class RunGovernorSettings(TypedDict):
    """The `governor` settings of `CrawlSettings`."""

    browser: NotRequired[RunGovernorBrowserSettings]

    run_share: NotRequired[int]
    """The share, in percent, of each kind's concurrency one Run may hold at once, at least one: 100. An Operator policy cap bounds every Run's share.

    `governor.run_share`.
    """


class RunIdentifiedSettings(TypedDict):
    """The `identified` settings of `CrawlSettings`."""

    signature_agent: NotRequired[str | None]
    """Where a site reads the key directory of an `identified` Session's key, sent with each signed request as `Signature-Agent`, in the string form Cloudflare accepts: the `https://` origin that serves `goodfetch signing-key directory`'s output at `/.well-known/http-message-signatures-directory`, such as `https://bot.example`, or an inline `data:application/http-message-signatures-directory;base64,` directory. None by default; an `identified` Session needs it, with `identified.signing_key`. Set where a Session that is not `identified` opens, `setting_not_applicable`; inherited, it yields to the Access mode. A Label refuses it with `setting_not_applicable`.

    `identified.signature_agent`.
    """

    signing_key: NotRequired[str | None]
    """The Secret reference of the Ed25519 key an `identified` Session signs each of its requests with (Web Bot Auth), such as `env:BOT_KEY`: never a value. It resolves to the key as a private JSON Web Key (`kty` `OKP`, `crv` `Ed25519`, with `d` and `x`), resolved once when the Session opens and never written to a log, a trace, a process's arguments or a file; a rotated key is read by the next Session. None by default; an `identified` Session needs it, with `identified.signature_agent`. Set where a Session that is not `identified` opens, `setting_not_applicable`; inherited, it yields to the Access mode. Set only by the program's own code, configuration and an Operator policy: a Recipe may expose it but never sets it, and a Client acting for a model is refused with `setting_locked`. A Label refuses it with `setting_not_applicable`.

    `identified.signing_key`.
    """


class RunLiveViewSettings(TypedDict):
    """The `live_view` settings of `CrawlSettings`."""

    hiding: NotRequired[Literal["auto", "off", "always"]]
    """Whether a Session's pages hide, on the live page, the elements the Filter lists' cosmetic rules match: `auto` (the default) and `always` hide them through a style sheet the site cannot see on Chromium, in every frame and every new document; `off` leaves the live page as served. When the guard finds an action's target hidden, it lifts the rule for the Session and acts. Extracted content has the elements removed whatever this says.

    `live_view.hiding`.
    """


class RunNetworkSettings(TypedDict):
    """The `network` settings of `CrawlSettings`."""

    max_body_size: NotRequired[int]
    """The most decoded bytes of one body the engine itself reads: a page `request`'s response, a kept response, an Operator-configured endpoint's reply. Never a download, which the disk governor bounds. 64 MiB (67108864) by default; set for a connection or a Run. A longer body fails the call with `response_limit_exceeded`.

    `network.max_body_size`.
    """

    max_decompression_ratio: NotRequired[int]
    """The most decoded bytes per received byte of a body the engine reads, once its decoded bytes pass 1 MiB, so a decompression bomb is stopped as it expands. 100 by default; set for a connection or a Run. A body past it fails the call with `response_limit_exceeded`.

    `network.max_decompression_ratio`.
    """

    max_json_depth: NotRequired[int]
    """The deepest nesting of arrays and objects in JSON the engine parses from outside, from 0 to 1024: 128 by default; set for a connection or a Run. Deeper JSON fails the call with `response_limit_exceeded`.

    `network.max_json_depth`.
    """

    resolve: NotRequired[Mapping[str, list[str]]]
    """Host names mapped to addresses before any lookup, in the engine's resolver and in Chromium, each address still checked by ADR 0017's resolved-address rule. Empty by default; an Operator policy can lock it.

    `network.resolve`.
    """


class RunPaidFetchSettings(TypedDict):
    """The `paid_fetch` settings of `CrawlSettings`."""

    domains: NotRequired[list[str]]
    """The registrable domains a run may pay for a page; `*` only when written. Widened only in an Operator policy, user or project configuration, or by a person's answer; a Recipe or a run only narrows it.

    `paid_fetch.domains`.
    """

    max_price_per_page: NotRequired[str | None]
    """The most a run pays for one page, as an amount and its currency such as `0.05 USD`; none by default. Raised only in configuration; a Recipe or a run only lowers it.

    `paid_fetch.max_price_per_page`.
    """


class RunPolitenessBackoffSettings(TypedDict):
    """The `politeness.backoff` settings of `CrawlSettings`."""

    enabled: NotRequired[bool]
    """Whether a domain that answers 429, 502, 503 or 504, or does not answer in time, is backed off, and its `Retry-After` waited out, for every run of the user that shares Politeness. Off, the run ignores both, and it is listed in the run's result.

    `politeness.backoff.enabled`.
    """

    initial: NotRequired[timedelta]
    """The shortest wait of a domain's backoff: each wait is drawn at random between it and three times the previous wait (the first between it and three times it), never above `politeness.backoff.max`: 2 s. A shorter value is listed in the run's result.

    `politeness.backoff.initial`.
    """

    max: NotRequired[timedelta]
    """The longest wait of a domain's backoff: 60 s. A `Retry-After` may hold the domain longer, up to `politeness.retry_after.max`. A shorter value is listed in the run's result.

    `politeness.backoff.max`.
    """


class RunPolitenessDomainSettings(TypedDict):
    """The `politeness.domain` settings of `CrawlSettings`."""

    adaptive_delay: NotRequired[bool]
    """Whether a domain key's delay between request starts lengthens as its responses slow: on, the delay is the longer of `politeness.domain.delay` and the exponentially weighted mean (weight 0.3) of the latency of its last responses on the `http` tier, that mean capped at `politeness.backoff.max`. It only lengthens the delay, never below `politeness.domain.delay`. Off by default.

    `politeness.domain.adaptive_delay`.
    """

    burst: NotRequired[int]
    """How many crawl requests may start at once on one domain key under `politeness.domain.rate`, the size of its token bucket: 1 by default, so the starts are spread evenly over the minute. A value of 0 is read as 1.

    `politeness.domain.burst`.
    """

    concurrency: NotRequired[int | None]
    """How many requests may be in flight at once on one domain key, counted across every run of the user that shares Politeness: a run admits one only while that combined count is below its own value. None by default until the fetch tiers set ADR 0086's default of 1. A value above 1 is listed in the run's result as one that presses a site harder.

    `politeness.domain.concurrency`.
    """

    delay: NotRequired[timedelta | None]
    """How long a run waits after the last request start on a domain key, by any run of the user that shares Politeness, before it starts another there. None by default until the fetch tiers set ADR 0086's default of 1 s. A value below 1 s is listed in the run's result as one that presses a site harder.

    `politeness.domain.delay`.
    """

    rate: NotRequired[int | None]
    """How many crawl requests a minute may start on one domain key, counted across every run of the user that shares Politeness, as a token bucket of `politeness.domain.burst` tokens refilled at this rate: 30 holds a site to 30 requests a minute. Each run is held to its own value; the delay between starts still applies. None by default.

    `politeness.domain.rate`.
    """


class RunPolitenessProxySettings(TypedDict):
    """The `politeness.proxy` settings of `CrawlSettings`."""

    concurrency: NotRequired[int | None]
    """How many page navigations may be in flight at once through one proxy endpoint and credential, counted across every run of the user that shares Politeness, each redirect hop of a page's main frame counted, a program's own navigation included (a page's other requests and `page.request` are not counted): a run sends one only while that combined count is below its own value and below the ceiling the proxy's own refusals taught. At least 1; none by default, for no cap.

    `politeness.proxy.concurrency`.
    """

    rate: NotRequired[int | None]
    """How many page navigations a second may start through one proxy endpoint and credential, counted across every run of the user that shares Politeness, each redirect hop of a page's main frame counted, a program's own navigation included (a page's other requests and `page.request` are not counted): a run starts one only once a second divided by its own value has passed since the last start there by any sharing run. None by default.

    `politeness.proxy.rate`.
    """


class RunPolitenessRetryAfterSettings(TypedDict):
    """The `politeness.retry_after` settings of `CrawlSettings`."""

    max: NotRequired[timedelta]
    """The longest a crawl waits for the time a site's `Retry-After` asks, past `politeness.backoff.max`: 15 minutes. When the site asks for longer, nothing is sent to its domain before that time and nothing waits for it: the request whose response asked, and each request admitted to the domain meanwhile, ends `failed` with `response_unavailable`, and `run.retry_failed` re-admits them once the site is back. Whatever its value, nothing is sent sooner than the site asked.

    `politeness.retry_after.max`.
    """


class RunPolitenessSettings(TypedDict):
    """The `politeness` settings of `CrawlSettings`."""

    backoff: NotRequired[RunPolitenessBackoffSettings]

    delegation: NotRequired[bool]
    """Whether a Run sharing Politeness takes each key's Delegation: while no other engine of the user uses a key, its engine keeps the key's Permits and state in memory, each Permit with no transaction on the Politeness file, and writes to the file at once what a site asked (a 429, a `Retry-After`, a backoff, a halved ceiling, a new Crawl-delay). Another engine that needs the key recalls it, and one whose holder is gone reclaims it, its delay counted from the reclaim. `false` takes and gives back each Permit in transactions of the file, unless the Run's engine already holds the key's Delegation for another Run: the Permit then comes from memory too, so the key's limits hold across both Runs. Ignored at `politeness.sharing: run`.

    `politeness.delegation`.
    """

    domain: NotRequired[RunPolitenessDomainSettings]

    proxy: NotRequired[RunPolitenessProxySettings]

    retry_after: NotRequired[RunPolitenessRetryAfterSettings]

    sharing: NotRequired[Literal["shared", "per_daemon", "run"]]
    """How a Run shares Politeness with the other runs of its user: `shared` with every engine of the user (through the Politeness store when one is configured, else on the machine), `per_daemon` on the machine only, ignoring a store, or `run` for Politeness of its own. Anything but `shared` is listed in the Run's result.

    `politeness.sharing`.
    """


class RunProvenanceSettings(TypedDict):
    """The `provenance` settings of `CrawlSettings`."""

    log: NotRequired[bool]
    """Whether the Run writes its Provenance log, `trace/provenance.jsonl` in its Run trace (ADR 0047): an entry for each step of a page or a request that its Records' own Provenance does not hold, such as the tier that fetched it, what the Clean-up rules removed from a page read, a hedge sent or a response shared. On by default. Off, no entry is masked, encoded or written, so the Run trace holds no Provenance log, while each Record still carries its own Provenance; it is recorded in the Audit log, listed in the run's result, and the Run report's warning `provenance_off` says so.

    `provenance.log`.
    """


class RunProxySettings(TypedDict):
    """The `proxy` settings of `CrawlSettings`."""

    bypass: NotRequired[str | None]
    """The hosts the Session reaches without its proxy, as Playwright's `bypass`: a comma-separated list such as `.example.com, chromium.org`, a leading dot naming a domain's subdomains. None by default: every request goes through `proxy.server`. Set as `proxy.server` is.

    `proxy.bypass`.
    """

    country: NotRequired[str | None]
    """The country, an ISO 3166-1 alpha-2 code such as `US`, a Session's proxy exit is in. None by default: any country the provider offers. A country the provider does not offer for the Session's proxy kind is refused with `setting_invalid` when the Session opens. A Recipe never sets it (`setting_locked`).

    `proxy.country`.
    """

    kind: NotRequired[Literal["datacenter", "isp", "residential", "mobile"] | None]
    """The proxy kind a Session's proxy is drawn from, `datacenter`, `isp`, `residential` or `mobile`: the provider's default when unset, for `list` the kind of its first server. A kind the provider does not offer is refused with `setting_invalid` when the Session opens. A Recipe may set it; a Client acting for a model is refused with `setting_locked`, since the kinds' prices differ by an order of magnitude and the person pays.

    `proxy.kind`.
    """

    password: NotRequired[str | None]
    """The Secret reference of the password the Session gives `proxy.server` with `proxy.username`, such as `env:PROXY_PASSWORD`: never a value, resolved when the Session opens and never written to a log, a trace, a process's arguments or a file. None by default. Set as `proxy.server` is.

    `proxy.password`.
    """

    provider: NotRequired[str | None]
    """The Proxy provider each Session of the Run, or the Session it is set on, draws its one proxy from when it opens, fixed for the Session's life: `bright_data`, `oxylabs` or `apify`, whose adapters build the provider's sticky-session username from the account in `proxy.providers.<name>` and ask for the provider's longest sticky lifetime, or `list`, the user's own servers in `proxy.providers.list.servers`. None by default. A Session that resolves both `proxy.server` and `proxy.provider` is refused with `setting_invalid`. Set as `proxy.server` is: a Recipe may expose it but never sets it, and a Client acting for a model is refused with `setting_locked`.

    `proxy.provider`.
    """

    server: NotRequired[str | None]
    """The proxy every request of the Session goes through, as Playwright's `server`: an `http://`, `https://`, `socks5://` or `socks5h://` URL with a host and a port, such as `http://proxy.example:3128`. None by default: the machine's own address. Set on a Run, every Session of it takes it; set in `run.new_session`'s `settings`, that Session alone; a page or a request has no proxy of its own, so the address a site sees never changes under the same cookies. A URL carrying credentials and `socks4` are refused with `setting_invalid`: give the credentials as `proxy.username` and `proxy.password`. Set only by the program's own code, configuration and an Operator policy: a Recipe may expose it but never sets it, and a Client acting for a model is refused with `setting_locked`, since whoever sets it receives `proxy.password`. On Chromium, a SOCKS5 proxy's credentials go through a loopback relay the engine opens for the Session.

    `proxy.server`.
    """

    sticky_lifetime: NotRequired[timedelta | None]
    """How long, in milliseconds, a Session asks its provider to keep its proxy exit: the provider's longest when unset. A Session that outlives it is named by the Run report's `proxy_exit_may_change` warning; the engine never looks the exit up. A `list` server's exit never changes.

    `proxy.sticky_lifetime`.
    """

    username: NotRequired[str | None]
    """The username the Session gives `proxy.server`, as Playwright's `username`. None by default. Set as `proxy.server` is.

    `proxy.username`.
    """


class RunResolverSettings(TypedDict):
    """The `resolver` settings of `CrawlSettings`."""

    attempt_delay: NotRequired[timedelta]
    """How long the engine's HTTP transports let a connection attempt to one of a host's addresses run before they start the next one beside it: 250 ms, RFC 8305's Connection Attempt Delay. An attempt that fails starts the next at once.

    `resolver.attempt_delay`.
    """

    resolution_delay: NotRequired[timedelta]
    """How long the engine's HTTP transports wait for a host's IPv6 addresses once its IPv4 addresses arrived first, before they start connecting over IPv4: 50 ms, RFC 8305's Resolution Delay.

    `resolver.resolution_delay`.
    """


class RunRunStateBatchSettings(TypedDict):
    """The `run_state.batch` settings of `CrawlSettings`."""

    bytes: NotRequired[int | Literal["none"]]
    """Write the Run's changes once they hold this many bytes of rows. This bounds the memory that changes not yet written take.

    `run_state.batch.bytes`.
    """

    interval: NotRequired[int | Literal["none"]]
    """Write the Run's changes at least this often. A crash loses at most about this much work.

    `run_state.batch.interval`.
    """

    pages: NotRequired[int | Literal["none"]]
    """Write the Run's changes once this many attempts have ended since the last batch. Lower loses less to a crash and writes more often.

    `run_state.batch.pages`.
    """

    per_attempt: NotRequired[bool]
    """Write each attempt's claim before its fetch and its outcome before anything is told outside, as its own batch. Slowest, and a crash then loses only the attempts in flight.

    `run_state.batch.per_attempt`.
    """

    sync: NotRequired[Literal["each", "interval", "never", "off"]]
    """Which batches reach the disk before the next one starts. `each` survives a power cut; `interval` syncs one batch per `run_state.commit_interval`; `never` survives a process crash only; `off` syncs nothing, so a crash discards the run file and the Run starts again.

    `run_state.batch.sync`.
    """


class RunRunStateMemorySettings(TypedDict):
    """The `run_state.memory` settings of `CrawlSettings`."""

    budget: NotRequired[int]
    """The most memory this Run's Frontier, Leases and changes not yet written may hold, in bytes. Past it, or under memory pressure, state already written leaves memory and is read back from the run file. 0 keeps the Frontier in the run file. A budget of 0 with `run_state.batch.pages`, `.interval` and `.bytes` all `none` is refused, since nothing would ever leave memory.

    `run_state.memory.budget`.
    """


class RunRunStateSettings(TypedDict):
    """The `run_state` settings of `CrawlSettings`."""

    batch: NotRequired[RunRunStateBatchSettings]

    commit_interval: NotRequired[timedelta]
    """How often `run_state.batch.sync: interval` syncs a batch, and an idle Run's last changes.

    `run_state.commit_interval`.
    """

    durability: NotRequired[Literal["full", "fast", "periodic", "batch", "off"]]
    """How a Run's state reaches the disk, its Durability level, each value a preset of `run_state.batch.*` and `run_state.commit_interval`: `batch`, the default, writes the Run's changes in Run-state batches, of 1,000 attempts, 1 s or 8 MiB, whichever comes first, each synced, so a crash or a power cut loses at most the last batch; `full` writes each attempt's claim and outcome as a synced batch of its own (`synchronous=FULL`, with `fullfsync` on macOS), so only the attempts in flight are lost; `fast` is `full` unsynced (`synchronous=NORMAL`): it survives a process crash only, since an OS crash or a power cut may roll back recent commits, possibly many, without damaging the run state; `periodic` is `fast` with one synced batch every `run_state.commit_interval`, so a power cut loses at most that interval of work; `off` writes as `batch` does and syncs nothing (`synchronous=OFF`), and a run file a crash or a power cut left is discarded when the Run is next started or resumed, so the Run starts again from nothing. A level unfolds into its preset's keys at the layer that set it: a key set at that layer or a higher one overrides the preset's value, and a lock on the level locks every key of its preset. At every level a clean stop writes and syncs everything, so a paused Run resumes. The run report's `weakened` names `off`, and each preset key whose value weakens the Run.

    `run_state.durability`.
    """

    location: NotRequired[str | None]
    """The folder that holds the run folders, each named by its Run ID; by default the per-user, per-major data folder of the Goodfetch home.

    `run_state.location`.
    """

    memory: NotRequired[RunRunStateMemorySettings]


class RunSampleSettings(TypedDict):
    """The `sample` settings of `CrawlSettings`."""

    echo_repeats: NotRequired[int]
    """How many times the sample operation repeats a text.

    `sample.echo_repeats`.

    Deprecated. Since 0.1, removed no earlier than 1.0: A sample setting, which the real catalog replaces.
    """


class RunSecretsSettings(TypedDict):
    """The `secrets` settings of `CrawlSettings`."""

    placeholders: NotRequired[Mapping[str, SecretsPlaceholdersEntry1 | SecretsPlaceholdersEntry2]]
    """Each Secret placeholder's binding, as `secrets.placeholders.<name>`: `reference`, the Secret reference its value comes from, with `totp: true` when that value is a TOTP seed whose current code is typed, or `code_source`, the email or SMS code source its one-time code comes from; and `domains`, required, the registrable domains its value may go to, each with its subdomains, `*` only when written. A host below a registrable domain, such as `www.example.com`, is refused with `setting_invalid` naming the domain. `secret("name")` in code and `%name%` in an AI instruction name the placeholder, and the nearest of a Session, its Run and the connection that binds it wins. None by default. A Recipe declares names and never binds one, and a Client acting for a model never sets one: either's value is `setting_locked`.

    `secrets.placeholders`.
    """

    resolve_each_use: NotRequired[list[str]]
    """The Secret references a Run resolves again at each use, such as a rotating token's. Any other reference is resolved once for each placeholder it fills and its value reused for the rest of the Run, its domain binding checked at each use; none by default.

    `secrets.resolve_each_use`.
    """


class RunSecuritySettings(TypedDict):
    """The `security` settings of `CrawlSettings`."""

    audit_chain: NotRequired[bool]
    """Whether the run's Audit log entries are hash-chained (ADR 0016). On by default; off, that run's entries are written unchained, each marked `chained: false`, which `audit verify` steps over while it verifies the chain around them; the switch itself is a chained entry, and the run says so in its report's `weakened` and in one warning.

    `security.audit_chain`.
    """

    field_encryption: NotRequired[bool]
    """Whether the run's state seals its secret fields with the run's data key (ADR 0015). On by default; off, they are written in the clear, and the run says so in its report's `weakened`, in the Audit log and in one warning.

    `security.field_encryption`.
    """

    raw_cdp_egress_proxy: NotRequired[bool]
    """Whether every browser Session the engine launches reaches the network through the egress relay, which holds a raw CDP client or a Lent page at the network layer (ADR 0017). On by default; off, a Session with no certificate exception and no local address connects directly, held by interception alone, and the run says so in its report's `weakened`, in the Audit log and in one warning. It never removes the relay that carries certificate exceptions or local addresses.

    `security.raw_cdp_egress_proxy`.
    """

    redaction: NotRequired[bool]
    """Whether logs, traces and HAR files are redacted and screenshots and recordings kept as outputs are masked (ADR 0014). On by default; off lifts that guarantee for those outputs only: secrets still never reach the model, Plans, caches, the Effect journal or observations. The run says so in its report's `weakened`, in the Audit log and in one warning.

    `security.redaction`.
    """

    resolved_ip_check: NotRequired[bool]
    """Whether every address a name resolves to is checked against the egress policy before a connection is made (ADR 0017). On by default; off, the domain policy alone applies, and the run says so in its report's `weakened`, in the Audit log and in one warning.

    `security.resolved_ip_check`.
    """

    secure_delete: NotRequired[bool]
    """Whether the run's secret tables overwrite what they delete, SQLite's `secure_delete` (ADR 0015). On by default; off, deleted values may stay on disk until overwritten, and the run says so in its report's `weakened`, in the Audit log and in one warning.

    `security.secure_delete`.
    """


class RunSessionPoolSettings(TypedDict):
    """The `session.pool` settings of `CrawlSettings`."""

    affinity: NotRequired[Literal["host", "none"]]
    """Which open Session with room a crawl's Session pool prefers for a request under `session.pool.growth: on_demand`. `host` prefers one whose last request went to the request's host; `none` draws among them at random. It never opens a Session.

    `session.pool.affinity`.
    """

    growth: NotRequired[Literal["on_demand", "eager"]]
    """When a crawl's Session pool opens a new Session. `on_demand` opens one only when no open Session of the client a request needs, at its domain's proxy tier, has room under `session.pool.session_concurrency`, or when a block that retired a Session leaves the domain owing one; a browser Session opens only while a browser page can be admitted for it, else the request waits for a browser Session with room. `eager` opens a new Session for every request while the pool is under `session.pool.max_size`, as Crawlee does.

    `session.pool.growth`.
    """

    max_age: NotRequired[timedelta]
    """How long after it opened a Session of a crawl's Session pool is retired: 3,000 s, Crawlee's `maxAgeSecs`.

    `session.pool.max_age`.
    """

    max_error_score: NotRequired[int]
    """The error score at which a Session of a crawl's Session pool is retired: 3. A block or a failed Page check adds 1, a success takes 0.5 off, never below 0 (Crawlee's model).

    `session.pool.max_error_score`.
    """

    max_size: NotRequired[int]
    """How many Sessions a crawl's Session pool keeps open at once, whether each sends from its own HTTP transport or from its browser: 100. A request goes to an open Session of the client it needs at its domain's proxy tier that has room under `session.pool.session_concurrency`, a new Session opening only when none has room and the pool is under this size; a full pool draws among the busy ones.

    `session.pool.max_size`.
    """

    max_uses: NotRequired[int]
    """How many requests one Session of a crawl's Session pool serves before it is retired: 50, Crawlee's `maxUsageCount`.

    `session.pool.max_uses`.
    """

    session_concurrency: NotRequired[int | None]
    """How many requests one Session of a crawl's Session pool serves at once under `session.pool.growth: on_demand`: 1. Unset, a Session serves any number, so the pool opens one Session for each client and proxy tier.

    `session.pool.session_concurrency`.
    """


class RunSessionSettings(TypedDict):
    """The `session` settings of `CrawlSettings`."""

    page_check: NotRequired[SessionPageCheck | None]
    """The Page check every page of a Session is judged against once its navigation reached its document: `login_page` and `expected_page`, each optional and each a page match, a URL glob or regular expression, a CSS or XPath selector, or a text. A page matching its login page raises `logged_out` from the call that waited for its navigation; one matching neither, when an expected page is given, raises `page_check_failed`. None by default: the built-in detector then judges a page a login page when the navigation was redirected to a login path, or when the page shows one password field outside a login path, and Provenance marks each page it judged as weakly checked. Set at a Run, a connection or a Session's own `settings`.

    `session.page_check`.
    """

    pool: NotRequired[RunSessionPoolSettings]

    source: NotRequired[SessionSourceSavedIdentity | SessionSourceStateFile | SessionSourceCookieHeader | SessionSourceProfileDirectory | SessionSourceInstalledBrowser | SessionSourceRunningBrowser | SessionSourceCDPURL | None]
    """Where a Session's login comes from: exactly one kind of ADR 0056's tagged union, or none for a fresh Session. Set at a Run or a connection, it is the default of the Sessions opened beneath; opening a Session takes its own as the call's `source`, and in that Session's own `settings` it is refused with `setting_not_applicable`. A Recipe never sets or locks it; it may only expose it to its users.

    `session.source`.
    """


class RunSitePreferencesSettings(TypedDict):
    """The `site_preferences` settings of `CrawlSettings`."""

    mark_robots_txt_ignored: NotRequired[bool]
    """Whether, while `site_preferences.respect_robots_txt` is off, each Record of a crawl request its origin's robots.txt disallows carries `robots_txt: "ignored"` in its Provenance, so that what was taken against a site's stated preferences can be found. Off by default, robots.txt is then not read for it. On, each origin's robots.txt is read once from the copy the user's runs share, and each request costs one match against it.

    `site_preferences.mark_robots_txt_ignored`.
    """

    max_crawl_delay: NotRequired[timedelta]
    """The longest robots.txt Crawl-delay a crawl waits out between request starts on a domain key while `site_preferences.respect_robots_txt` is on: 30 s. A host asking for more has its crawl requests skipped with `crawl_delay`, and its delay is not raised.

    `site_preferences.max_crawl_delay`.
    """

    purpose: NotRequired[Literal["search", "ai-input", "ai-train", "collect"]]
    """What the run's results are for, against which the AI-use signals are judged while `site_preferences.respect_use_signals` is on: `search` (the default, which no signal is judged against), `ai-input` (input to an AI model), `ai-train` (training an AI model) or `collect` (plain collection, text and data mining).

    `site_preferences.purpose`.
    """

    respect_robots_txt: NotRequired[bool]
    """Whether every crawl request, start URLs and sitemap entries included, and every navigation a handler makes, obeys the site's robots.txt (RFC 9309): a request it disallows, or one waiting on a robots.txt that answers 429 or 5xx or no answer, with no earlier copy, until its retries ran out, ends `skipped` with `robots_txt` and its handler never runs. On by default. Off, robots.txt is neither fetched, read nor stored, and no Crawl-delay is recorded from it, unless `site_preferences.mark_robots_txt_ignored` marks the Records taken against it, the AI-use signals read its `Content-Signal` lines, or a sitemap seed names it for its `Sitemap` lines; its rules are then not applied, and it is listed in the run's result as a value that presses a site harder.

    `site_preferences.respect_robots_txt`.
    """

    respect_use_signals: NotRequired[bool]
    """Whether the AI-use signals a site sends (IETF aipref's `Content-Usage` header, TDMRep's `tdm-reservation` header) are applied to the run's `site_preferences.purpose`: on, a crawl request whose response's signal refuses the Purpose ends `skipped` with `use_signals` and its handler never runs. Off by default; the signals are read either way.

    `site_preferences.respect_use_signals`.
    """

    robots_txt_user_agent: NotRequired[str | None]
    """The operator's own robots.txt product token, letters, `_` and `-`: a crawl obeys the robots.txt groups naming it merged with those naming `goodfetch-foxhound`, each matched as a whole token in any case, and the `*` group only when neither has one. None by default. A value is listed in the run's result as one that presses a site harder.

    `site_preferences.robots_txt_user_agent`.
    """


class RunStealthIdentitySettings(TypedDict):
    """The `stealth.identity` settings of `CrawlSettings`."""

    brand: NotRequired[list[str]]
    """The browser brands a `stealth` Session's generated identity is drawn from; empty by default, which draws from real traffic's shares. A Label refuses it with `setting_not_applicable`.

    `stealth.identity.brand`.
    """

    device: NotRequired[list[str]]
    """The devices a `stealth` Session's generated identity is drawn from; empty by default, which draws from real traffic's shares. A Label refuses it with `setting_not_applicable`.

    `stealth.identity.device`.
    """

    os: NotRequired[list[str]]
    """The operating systems a `stealth` Session's generated identity is drawn from; empty by default, which draws from real traffic's shares. A Label refuses it with `setting_not_applicable`.

    `stealth.identity.os`.
    """


class RunStealthSettings(TypedDict):
    """The `stealth` settings of `CrawlSettings`."""

    chromium_build: NotRequired[Literal["goodfetch", "fingerprint_chromium", "clearcote"]]
    """The Chromium build a `stealth` Session runs: `goodfetch` (the default), `fingerprint_chromium` or `clearcote`, the last two only where `stealth.allowed_builds` allows their digest. A Label refuses it with `setting_not_applicable`.

    `stealth.chromium_build`.
    """

    fingerprint_method: NotRequired[Literal["none", "js_injection", "basic", "engine"]]
    """How a `stealth` Session masks its browser's fingerprint: `none`, `js_injection`, `basic` or `engine`, the default under `stealth`; `none` elsewhere. Any method but `none` makes the Session `stealth`, its other items keeping the values set and the rest taking `stealth`'s defaults. A Label refuses it with `setting_not_applicable`.

    `stealth.fingerprint_method`.
    """

    generated_identity: NotRequired[bool]
    """Whether a `stealth` Session runs under an identity generated from real traffic's shares: `true` under `stealth`, `false` elsewhere. Off, the Goodfetch Chromium keeps its own identity, matched to the exit as in `standard`. A Label refuses it with `setting_not_applicable`.

    `stealth.generated_identity`.
    """

    human_input: NotRequired[bool]
    """Whether a `stealth` Session moves, clicks and types as a person does: `true` under `stealth`, `false` elsewhere. A Label refuses it with `setting_not_applicable`.

    `stealth.human_input`.
    """

    identity: NotRequired[RunStealthIdentitySettings]


class RunTimeoutSettings(TypedDict):
    """The `timeout` settings of `CrawlSettings`."""

    action: NotRequired[timedelta]
    """How long a locator action waits for its target to be unique and actionable, and replays a gesture that landed elsewhere, before it fails with `deadline_exceeded`, or `target_not_unique` for a target still ambiguous: 30 s.

    `timeout.action`.
    """

    agent: NotRequired[timedelta]
    """How long an Agent's task may run, its actions and model calls nested inside, before it stops with `ended: stopped` and the reason `timeout`: 10 min.

    `timeout.agent`.
    """

    ai: NotRequired[timedelta]
    """How long an AI verb may take from its call to its return, its model calls and a Repair included, before it fails with `deadline_exceeded`: 120 s.

    `timeout.ai`.
    """

    close: NotRequired[timedelta]
    """One bound for a stop of a Run: how long `run.stop` or a scope's close waits for its next safe point before it fails with `deadline_exceeded`, the Run still stopping there, and how long that safe point then waits for each running Effect body's `effect.close` before it cuts the body short, in a drain no later than half of `daemon.drain_grace` from the drain's start: 30 s.

    `timeout.close`.
    """

    dataset_query: NotRequired[timedelta]
    """How long one `dataset.query` may run before it is stopped and fails with `deadline_exceeded`: 30 s.

    `timeout.dataset_query`.
    """

    first_byte: NotRequired[timedelta]
    """How long a request may wait for its response's first byte before its attempt fails with `deadline_exceeded`: 30 s.

    `timeout.first_byte`.
    """

    handler: NotRequired[timedelta]
    """How long a crawl's handler has for one attempt, which also bounds every action inside it, and from which a work item's lease is derived: the timeout plus the larger of 10 s and a tenth of it. 60 s, Crawlee's `requestHandlerTimeoutSecs`.

    `timeout.handler`.
    """

    hook: NotRequired[timedelta]
    """How long each call of a Hook may run before it fails with `deadline_exceeded`: 10 s. A crawl's Label may set it for the Hooks on its requests.

    `timeout.hook`.
    """

    human_pause: NotRequired[timedelta]
    """How long a Human pause may wait for a person before it fails with `deadline_exceeded`: 24 h; in a scheduled run, ADR 0036's pause timeout governs too, and the first to expire acts.

    `timeout.human_pause`.
    """

    launch: NotRequired[timedelta]
    """How long a browser the engine launches, or a Borrowed one it connects to, may leave each command of its bring-up unanswered, its identity read's page load included, before the call that needs it fails with `deadline_exceeded`: 30 s, Playwright's default.

    `timeout.launch`.
    """

    model: NotRequired[timedelta]
    """How long one attempt of one model request may take before it is retried within the call that made it: 60 s.

    `timeout.model`.
    """

    navigation: NotRequired[timedelta]
    """How long a navigation may take before its attempt fails with `deadline_exceeded`: 30 s, Playwright's default.

    `timeout.navigation`.
    """

    secret: NotRequired[timedelta]
    """How long a Secret provider may take to answer one reference before the resolution fails with `secret_unavailable`, `failure: "timed_out"`: 30 s. A provider that answers it is briefly busy, such as a rate limit's, is asked again within it, with exponential backoff and full jitter, after its `Retry-After` when it gave one.

    `timeout.secret`.
    """

    sink_write: NotRequired[timedelta]
    """How long one write to a Sink may take before it fails with `deadline_exceeded`: 30 s.

    `timeout.sink_write`.
    """

    wait: NotRequired[timedelta]
    """How long a wait for an application state, such as `page.wait_for_request_finished`, may take before it fails with `deadline_exceeded`: 30 s.

    `timeout.wait`.
    """


class RunTlsSettings(TypedDict):
    """The `tls` settings of `CrawlSettings`."""

    accept_invalid_certs: NotRequired[Mapping[str, str | None]]
    """Domains whose certificate may fail verification, each with a pin, `any`, or `null` for trust on first use. A pin and `any` are taken only from an Operator policy and user and project configuration; a Recipe or a run may list a domain only for trust on first use.

    `tls.accept_invalid_certs`.
    """

    client_certificates: NotRequired[Mapping[str, TlsClientCertificatesEntry]]
    """Client certificates for mutual TLS by domain: a host or a registrable domain with its subdomains, mapped to a table of `certificate`, the file of the certificate and its chain (PEM or DER), and `key`, the Secret reference of its private key, such as `env:CLIENT_KEY`, resolved only when a handshake with a host of that domain starts; a key given as a value is refused with `setting_invalid`. The certificate goes to the domain's hosts and nowhere else, and never to a host reached through an exception of `tls.accept_invalid_certs`. Set from every layer, a Recipe and a run included; nothing is installed on the machine.

    `tls.client_certificates`.
    """


class RunWallSettings(TypedDict):
    """The `wall` settings of `CrawlSettings`."""

    domains: NotRequired[list[str]]
    """The domains whose Walls a run may read past by generic means. A Recipe or a run only narrows it; it is widened only in configuration or by a person's answer.

    `wall.domains`.
    """

    refetch_domains: NotRequired[list[str]]
    """The domains on which reading past a Wall may fetch a page again. A Recipe or a run only narrows it; it is widened only in configuration, never by an answer.

    `wall.refetch_domains`.
    """


class CrawlSettings(TypedDict):
    """The settings starting a crawl takes, Collie's and Foxhound's, which its Labels and requests inherit (ADRs 0083 and 0093).

    A key left out inherits, `None` clears a setting that can be cleared,
    and a value sets it; durations are `timedelta`s (ADR 0083).
    """

    admission: NotRequired[RunAdmissionSettings]

    browser: NotRequired[RunBrowserSettings]

    browser_cache: NotRequired[RunBrowserCacheSettings]

    checkpoint: NotRequired[RunCheckpointSettings]

    clean_up: NotRequired[RunCleanUpSettings]

    consent: NotRequired[RunConsentSettings]

    content: NotRequired[RunContentSettings]

    crawl: NotRequired[RunCrawlSettings]

    dataset: NotRequired[RunDatasetSettings]

    effect: NotRequired[RunEffectSettings]

    egress: NotRequired[RunEgressSettings]

    export: NotRequired[RunExportSettings]

    extraction: NotRequired[RunExtractionSettings]

    fetch: NotRequired[RunFetchSettings]

    filter_lists: NotRequired[RunFilterListsSettings]

    frontier: NotRequired[RunFrontierSettings]

    governor: NotRequired[RunGovernorSettings]

    identified: NotRequired[RunIdentifiedSettings]

    live_view: NotRequired[RunLiveViewSettings]

    network: NotRequired[RunNetworkSettings]

    paid_fetch: NotRequired[RunPaidFetchSettings]

    politeness: NotRequired[RunPolitenessSettings]

    provenance: NotRequired[RunProvenanceSettings]

    proxy: NotRequired[RunProxySettings]

    resolver: NotRequired[RunResolverSettings]

    run_state: NotRequired[RunRunStateSettings]

    sample: NotRequired[RunSampleSettings]

    secrets: NotRequired[RunSecretsSettings]

    security: NotRequired[RunSecuritySettings]

    session: NotRequired[RunSessionSettings]

    sinks: NotRequired[Mapping[str, SinksEntry]]
    """The Sinks a crawl's Run delivers its Records to, each by its name, as `sinks.<name>.*`: `type`, the catalog destination, left out for a program's own Sink handler of that name; `datasets`, the Datasets it receives; `mode`, `append` (the default), `upsert`, `insert_only`, `replace` or `history`; `key`, the fields a keyed mode uses, each Dataset's own key when left out; `deliver`, `records`, `files` or `both`; `destination`, the Secret reference of its DSN, URL or credentials, a value given in its place being refused with `setting_invalid`; `target`, its table, collection, index, topic, queue, sheet or object prefix; and `files`, `schema`, `rate`, `batch`, `webhook`, `embedding` and `image`, which only some types take. Every delivery carries its delivery ID, the Record's Dataset and number and the run epoch. None by default. Set on a connection or a crawl's Run, from code, the project file, the CLI or a Recipe; a Label refuses it with `setting_not_applicable`.

    `sinks`.
    """

    site_preferences: NotRequired[RunSitePreferencesSettings]

    stealth: NotRequired[RunStealthSettings]

    timeout: NotRequired[RunTimeoutSettings]

    tls: NotRequired[RunTlsSettings]

    wall: NotRequired[RunWallSettings]


class LabelContentSettings(TypedDict):
    """The `content` settings of `LabelSettings`."""

    extractor: NotRequired[Literal["dom_smoothie", "trafilatura"]]
    """The main-content step `page.formats` reads a page's main content with, before its Markdown, its main HTML and its text: `dom_smoothie` (the default), Readability's algorithm, or `trafilatura`, the rs-trafilatura port. A step that finds no text in a document holding text outside its navigation landmarks answers that text. Set at any scope down to a page: a Run, a Session's or a page's own `settings`.

    `content.extractor`.
    """


class LabelCrawlRetrySettings(TypedDict):
    """The `crawl.retry` settings of `LabelSettings`."""

    handler_failed: NotRequired[bool]
    """Whether a work item whose handler failed with `handler_failed`, or whose Hook in code failed with `hook_failed` on the program's own exception, is tried again: `false`. A Label may set it for its requests.

    `crawl.retry.handler_failed`.
    """


class LabelCrawlSettings(TypedDict):
    """The `crawl` settings of `LabelSettings`."""

    content_types: NotRequired[list[str]]
    """The media types a Label's handler takes, each `type/subtype`, `type/*` or `*/*`, set for the Run or for one of its Labels, whose own list wins for its requests: `text/html` and `application/xhtml+xml` by default. A response that would reach the handler (a 2xx, or a status `crawl.handle_statuses` lists) of another type ends its request `skipped` with the reason `content_type` before its body is read, never retried. The type is the response's `Content-Type` essence, or, when it names none, the type the pinned Chromium's MIME sniffer gives its first 1,024 bytes; a response with neither a type nor a body is an empty HTML document. An accepted type that is not HTML or XHTML reaches the handler with its body in its response and a page holding no document, whose document calls fail with `response_not_document`. A handler's own navigations are not checked. A value that is no list of media ranges is refused with `setting_invalid` when the crawl starts.

    `crawl.content_types`.
    """

    keep_url_fragment: NotRequired[bool]
    """Whether a crawl request's identity keeps its URL's fragment, so a hash-routed app's views (`#/a`, `#/b`) are separate requests, set for the Run or for one of its Labels, whose own value wins for its requests (Crawlee's `keepUrlFragment`). Off by default: one URL with two fragments is one request. Only the tiers that run the page's scripts serve such a request: under `fetch.tier: auto` it runs on `browser`, and forcing `http`, `browser_fetch` or `discovered_api` where it is on fails the crawl's start with `setting_not_applicable`. Fixed for a Run's life: a start under the Run's ID that changes it is refused with `setting_not_applicable`.

    `crawl.keep_url_fragment`.
    """

    retry: NotRequired[LabelCrawlRetrySettings]


class LabelFetchKeptResponsesSettings(TypedDict):
    """The `fetch.kept_responses` settings of `LabelSettings`."""

    urls: NotRequired[list[str]]
    """URL patterns, each a glob or a regular expression matched in the engine, naming the responses of a crawl request's own navigation kept for its handler's `keptResponse` and `keptResponses`, set for the Run or for one of its Labels, whose own list wins for its requests. None by default: nothing is kept. Only a tier that runs the page's scripts, or `discovered_api`, can keep them: forcing `http` or `browser_fetch` where a list is set fails the crawl's start with `setting_not_applicable`; any other list set is refused at the start with `capability_unavailable` until the engine keeps responses.

    `fetch.kept_responses.urls`.
    """


class LabelFetchSettings(TypedDict):
    """The `fetch` settings of `LabelSettings`."""

    encoding: NotRequired[str | None]
    """The encoding forced on each crawl request's own document after its BOM, a WHATWG Encoding label such as `shift_jis`, set for the Run or for one of its Labels; none by default. It stands where ADR 0119's order puts it: after the BOM, before the `Content-Type` charset, the `<meta>` prescan and UTF-8. It applies to the request's own document on every attempt, not to a handler's own navigations. A value that is no Encoding label is refused with `setting_invalid` when the crawl starts.

    `fetch.encoding`.
    """

    http_from: NotRequired[Literal["browser", "learned", "transport"]]
    """Where a Label's HTTP leaves from where the engine chooses its tier, under `fetch.tier: auto`, set for the Run or for one of its Labels; a forced `fetch.tier` ignores it. `browser` sends a sample's `http` run and a Label learned onto `http` from inside the Session's browser, recorded as `browser_fetch`, so the site meets one TLS fingerprint and one cookie jar. `transport` sends them from a Session's own HTTP transport, over its own TLS fingerprint and headers, recorded as `http`: a sample's `http` run and its `browser` run are drawn from two Sessions, one of each client, which share no cookie, storage or local address, and a Label learned onto `http` sends its documents, their redirect hops and its served pages' requests from a Session's own transport. `learned` (the default) behaves as `transport` until the engine learns per Label which client a site accepts: a sample whose `http` run differed runs once more from inside the browser, as does its replay of its browser's calls on `discovered_api`, and its Label keeps the cheapest client that matched every sample. Under either, a request a Session's own transport sent on the tier its Label's comparison chose, which the site refuses as `ip_block` (a 403 whose page says the visitor is blocked; a bare 401 or 403 is no block), retires that Session and drops the Label's choice on the domain: the request runs again as a sample, retried under the Run's retry policy, whose comparison may move the Label to `browser_fetch` or `browser`, and the domain's proxy tier moves up only where the browser's run is refused too. A choice learned under one value is sampled again under another that no longer allows its sender. A pool whose Sessions hold a login, set by a `session.source` or, for a Label's own pool, by its `login`, sends from the browser whatever this says, so the login is never shown under a second client: `config explain` names the Run's `session.source` in this key's `yields_to`, and a `transport` set where such a pool's Sessions open, by the Run on its own pool or by a Label on its pool, fails the crawl's start with `setting_locked`; HTTP credentials and secrets alone hold no login. `transport` is a weakened control, named in the Run report's `weakened` and recorded in the Audit log as `feature_switched_off`; `learned`, the default, and `browser` are not reported weakened.

    `fetch.http_from`.
    """

    kept_responses: NotRequired[LabelFetchKeptResponsesSettings]

    tier: NotRequired[Literal["auto", "http", "discovered_api", "browser_fetch", "light_browser", "browser"]]
    """The tier that fetches each crawl request's document, set for the Run or for one of its Labels: `auto` (the default) lets the engine choose, whether set or left at the built-in default: it learns the tier per Label on each domain by sample comparison, the first `fetch.sample.count` requests (3) of a Label on a domain each run on `http` and then on `browser`, whose run commits (sent from one Session, or from two that share nothing where `fetch.http_from` sends the Label's HTTP from the transport), and, under `fetch.http_from: learned`, where its `http` run differed, once more on `browser_fetch` from the hop page of the browser run's Session, its run discarded, the Label moving to `http` once all of them staged the same Records (compared after Unicode NFC and whitespace normalization of their strings, in any order) and the same enqueues, the browser's run never matching where it ended on another URL or read its document in another `document.characterSet`, and staying on `browser` for the Run where its browser sample met a consent wall; split by the first segment of its URL paths when its samples disagree by segment (a segment whose own samples disagree stays on `browser`; at most 16 segments per Label and domain, the rest on `browser`), to `browser_fetch` under `learned` once every sample matched there or over `http`, and on `browser` otherwise; a choice is sampled again as `fetch.sample.refresh_after` says; the choice is kept in the run file, so a resumed crawl takes it again, and Provenance records the tier that sent each attempt's document, `browser_fetch` where a document tier's request left from inside the Session's browser, as it does under `auto` unless `fetch.http_from` sends it from the Session's own transport, and whether it was forced; a request on `http` escalates to the browser at the first call that tier cannot serve exactly, in a Session of its own whose client is its browser where the request was sent from a Session's own transport; `http` and `browser` force those tiers, nothing escalating, and a call the forced tier cannot serve fails with `browser_required`; a `standard` Session forced onto `http` sends from its own transport, which presents its browser's `User-Agent` and document request headers (where the browser is an installed one, such as the distribution's Chromium on Linux arm64 and musl, those of the version its executable prints for `--version`, read once per Run without starting a browser; none, with the Run warned `browser_version_unread`, where no browser is installed or it does not print a version and exit within 10 seconds), as do the reads of robots.txt, sitemaps and AI-use signal files that transport sends under every tier, and keeps the Session's cookies in a jar of its own, over reqwest's TLS fingerprint, not the browser's; `light_browser` forces the Lightpanda tier where `fetch.light_browser` allows it, and under `auto` a Run that allows it also runs a sample on `light_browser` where its `http` run differed, the Label moving to `light_browser` once every sample matched there or over `http`; under `auto`, a sample whose `http` run escalated at a network wait also runs on `discovered_api` once its browser run answered: the JSON calls the browser's page made, read as a page-number or cursor plan, are replayed over HTTP for the same request, from the client its `http` run was sent from, and under `fetch.http_from: learned` once more from inside the Session's browser where that replay differed, each replayed call passing the navigation gate, a `page.wait_for_response` armed before a navigation of its page answered from the calls that navigation replays and any other escalating, and a Label whose samples all matched there, or over `http`, moves to `discovered_api`, its later requests replaying the plan for their own pages from the client every sample's replay matched from, its own transport where each matched there and the browser otherwise, which Provenance names in `calls_sent_on`; `browser_fetch` forces the HTTP tier sent from inside the Session's browser context, the one tier that sends HTTP with the browser's own TLS fingerprint, its cookies the Session's, nothing escalating; forcing `discovered_api` is refused with `capability_unavailable` at the crawl's start until a forced tier takes its browser sample.

    `fetch.tier`.
    """


class LabelSessionSettings(TypedDict):
    """The `session` settings of `LabelSettings`."""

    page_check: NotRequired[SessionPageCheck | None]
    """The Page check every page of a Session is judged against once its navigation reached its document: `login_page` and `expected_page`, each optional and each a page match, a URL glob or regular expression, a CSS or XPath selector, or a text. A page matching its login page raises `logged_out` from the call that waited for its navigation; one matching neither, when an expected page is given, raises `page_check_failed`. None by default: the built-in detector then judges a page a login page when the navigation was redirected to a login path, or when the page shows one password field outside a login path, and Provenance marks each page it judged as weakly checked. Set at a Run, a connection or a Session's own `settings`.

    `session.page_check`.
    """

    source: NotRequired[SessionSourceSavedIdentity | SessionSourceStateFile | SessionSourceCookieHeader | SessionSourceProfileDirectory | SessionSourceInstalledBrowser | SessionSourceRunningBrowser | SessionSourceCDPURL | None]
    """Where a Session's login comes from: exactly one kind of ADR 0056's tagged union, or none for a fresh Session. Set at a Run or a connection, it is the default of the Sessions opened beneath; opening a Session takes its own as the call's `source`, and in that Session's own `settings` it is refused with `setting_not_applicable`. A Recipe never sets or locks it; it may only expose it to its users.

    `session.source`.
    """


class LabelTimeoutSettings(TypedDict):
    """The `timeout` settings of `LabelSettings`."""

    hook: NotRequired[timedelta]
    """How long each call of a Hook may run before it fails with `deadline_exceeded`: 10 s. A crawl's Label may set it for the Hooks on its requests.

    `timeout.hook`.
    """


class LabelSettings(TypedDict):
    """The settings a crawl's Label takes, over its Run's, which its requests inherit (ADR 0093); a Label is refused every other key.

    A key left out inherits, `None` clears a setting that can be cleared,
    and a value sets it; durations are `timedelta`s (ADR 0083).
    """

    content: NotRequired[LabelContentSettings]

    crawl: NotRequired[LabelCrawlSettings]

    fetch: NotRequired[LabelFetchSettings]

    session: NotRequired[LabelSessionSettings]

    timeout: NotRequired[LabelTimeoutSettings]


